  static String _normalize(String value) {
    return value.toLowerCase()
      .replaceAll(RegExp(r'[ًٌٍَُِّْـٰ]'), '')
      .replaceAll(RegExp(r'[أإآٱ]'), 'ا')
      .replaceAll('ى', 'ي')
      .replaceAll('ة', 'ه')
      .replaceAll(RegExp(r'[^ء-يa-z0-9 ]'), ' ')
      .replaceAll(RegExp(r'\s+'), ' ')
      .trim();
  }

  static String? answer(String question) {
    final q = _normalize(question);
    if (q.isEmpty) return null;
    final qTokens = q.split(' ').where((e) => e.length > 1).toSet();
    Map<String, String>? best;
    var bestScore = 0.0;
    for (final entry in entries) {
      final phrases = entry['keys']!.split(';').map(_normalize).toList();
      for (final phrase in phrases) {
        if (q.contains(phrase) || phrase.contains(q)) return entry['answer'];
      }
      final tokens = phrases.expand((p) => p.split(' ')).where((e) => e.length > 1).toSet();
      final overlap = qTokens.intersection(tokens).length;
      final score = qTokens.isEmpty ? 0.0 : overlap / qTokens.length;
      if (overlap >= 2 && score > bestScore) {
        bestScore = score;
        best = entry;
      }
    }
    return bestScore >= .67 && best != null ? best['answer'] : null;
  }
